import{_ as t,o as r,c as a,ae as p}from"./chunks/framework.Iv6F95cJ.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/network-talk/第2季回归 - 这次我们来“趣谈Linux操作系统”.md","filePath":"books/network-talk/第2季回归 - 这次我们来“趣谈Linux操作系统”.md"}'),o={name:"books/network-talk/第2季回归 - 这次我们来“趣谈Linux操作系统”.md"};function n(_,e,i,s,m,u){return r(),a("div",null,[...e[0]||(e[0]=[p('<p>你好，我是你的老朋友刘超。在“趣谈网络协议”结课半年之后，我又给你带来了一个新的基础课程，“趣谈Linux操作系统”。</p><p>在咱们“趣谈网络协议”的留言里，我和同学们进行了很多互动，同时，我也和其他做基础知识专栏的作者有了不少交流，我发现，无论是从个人的职业发展角度，还是从公司招聘候选人的角度来看，扎实的基础知识是很多人的诉求。这让我更加坚信，我应该在“趣谈基础知识”这条道路上走下去。</p><p><strong>在设计“趣谈Linux操作系统”专栏的时候，我仍然秉承“趣谈”和“故事化”的方式，将枯燥的基础知识结合某个场景，给你生动、具象地讲述出来，帮你加深理解、巩固记忆、夯实基础。</strong></p><p>在我看来，操作系统在计算机中承担着“大管家”的角色，这个“大管家”就好比一家公司的老板，我们的目标就是把这家公司做上市，具体的过程，我用了一张图来表示：</p><p><img src="https://static001.geekbang.org/resource/image/7d/a5/7d7b2f705d4877bb331b4ea3ff3450a5.jpg?wh=2061%2A1303" alt="" loading="lazy" referrerpolicy="no-referrer"></p><p>Linux操作系统中的概念非常多，数据结构也很多，流程也复杂，一般人在学习的过程中很容易迷路。我希望能够将这些复杂的概念、数据结构、流程通俗地讲解出来，争取每篇文章都用一张图串起这篇的知识点。</p><p>最终，整个专栏下来，你如果能把这些图都掌握了，你的知识就会形成体系和连接。在此基础上再进行深入学习，就会如鱼得水、易如反掌。</p><p>一段新的征途即将开始，期待与你继续同行。为了感谢老同学，我为你送上一张10元专属优惠券，可以与限时优惠同享，优惠券有效期仅5天，建议你抓紧使用。点击下方图片，可试读专栏最新文章。</p><p>我们新专栏见！</p><p><a href="https://time.geekbang.org/column/intro/164?utm_term=zeusOLMNR&amp;utm_source=app&amp;utm_medium=geektime&amp;utm_campaign=164-presell&amp;utm_content=qutanwangluoxieyi" target="_blank" rel="noreferrer"><img src="https://static001.geekbang.org/resource/image/57/44/57f047be7ebb1f4aba7e8064e1c11544.jpg?wh=1342%2A638" alt="" loading="lazy" referrerpolicy="no-referrer"></a> 精选留言（15） return 👍（12） 💬（1）必须捧场， 铁杆。虽然网络协议还没学完， 但是 http原理搞懂了😆。 最爱的刘超老师和王铮老师2019-03-25C J J 👍（2） 💬（1）已购。请问老师你这思维导图是用哪个软件画的？看起来相当舒服。2019-03-26明天更美好 👍（0） 💬（1）刘老师，请教个问题，全部内网部署，还要做双中心，您这又现成的方案之类的吗2019-09-02陳先森 👍（0） 💬（1）已购，支持一下老师。2019-07-31谢晋 👍（0） 💬（1）超级棒的专题，非常细致，刘老师很用心！2019-05-12B L O U 👍（0） 💬（1）还想请教一下，老师是否能加个餐：</p><p>MIXIN是一个无限吞吐的链接所有现存区块链的移动端区块链网络，采用了DAG技术，链接所有现存的区块链网络，是一个跨链网络协议</p><p>能否解释一下垮链网络协议？感激不尽2019-04-14jason0606 👍（10） 💬（0）超哥, 还想你出一下关于容器方面的课程, 看了你的趣谈网络, 趣谈linux, 继续出一个容器的专题, 感觉就可以这三个内容串起来了呀2019-10-18Wisdom 👍（2） 💬（0）期待2019-03-25夜空中最亮的星 👍（2） 💬（0）那我必须去捧场了2019-03-25Dream 👍（1） 💬（0）已购，谢谢老师分享2019-03-25面朝大海春暖花开 👍（1） 💬（0）必须支持，老学员！！2019-03-25微秒 👍（1） 💬（0）肯定得听，操作系统闻名已久啊2019-03-25piboye 👍（0） 💬（0）老师，网络体系很大，有什么好的书籍或者路线推荐不？2022-07-18Jose 👍（0） 💬（0）立马入手2021-05-02ISA007 👍（0） 💬（0）已经买了，读完这本教程，开始攻克Linux.2021-02-23</p>',12)])])}const g=t(o,[["render",n]]);export{c as __pageData,g as default};
